  heading,
  description,
  showToggle,
  initialUnit,
}: ConvertibleTableSectionProps) => {
  const [unit, setUnit] = useState<Unit>(initialUnit);

  useEffect(() => {
    setUnit(initialUnit);
  }, [initialUnit, table]);

  const hasConvertibleRows = table.rows.some((r) => r.convertible);

  return (
    <TableSection
      heading={heading}
      description={description}
      toggle={showToggle && hasConvertibleRows ? <UnitToggle unit={unit} onChange={setUnit} /> : undefined}
    >
      <ScrollableTable table={table} unit={unit} />
    </TableSection>
  );
};

// Contentful's Object type has no structural validation — a published table field can be {}
// (or any other truthy object). Guard before passing to toDisplayRows/ZimmTable, which call
// table.rows.map/some unconditionally and throw on undefined.
const isValidTable = (t: SizeGuideTable): boolean =>
  Array.isArray(t.columns) &&
  Array.isArray(t.rows) &&
  t.rows.every((r) => r !== null && typeof r === 'object' && Array.isArray(r.values));

export const SizeGuideContent = ({ sizeFit, sizeGuide }: SizeGuideContentProps) => {
  const rawDefault = sizeGuide?.fields.defaultUnit;
  const initialUnit: Unit = rawDefault === 'cm' || rawDefault === 'inch' ? rawDefault : 'cm';

  const { fields } = sizeGuide ?? {};
  const sizeConversionsTable =
    fields?.sizeConversionsTable && isValidTable(fields.sizeConversionsTable)
      ? fields.sizeConversionsTable
      : undefined;
  const bodyMeasurementsTable =
    fields?.bodyMeasurementsTable && isValidTable(fields.bodyMeasurementsTable)
      ? fields.bodyMeasurementsTable
      : undefined;
  const garmentMeasurementsTable =
    fields?.garmentMeasurementsTable && isValidTable(fields.garmentMeasurementsTable)
      ? fields.garmentMeasurementsTable
      : undefined;
  const hasTables = !!sizeConversionsTable || !!bodyMeasurementsTable || !!garmentMeasurementsTable;

  // Normalise the fallback image URL to https and pre-build responsive variants using the
  // Contentful Images API (?w + ?fm without ?h/fit=fill so the image is width-constrained
  // rather than cropped to a fixed box — aspect ratio of this editorial asset is unknown).
  // Sizes: drawer content fills 100vw on mobile, capped at ~600px on tablet+ (TABLET_MIN_WIDTH).
  // Quality matches contentfulImage.ts's established constants (AVIF_QUALITY=65, WEBP_QUALITY=95).
  const fallbackImgBase = fields?.image
    ? fields.image.fields.file.url.startsWith('//')
      ? `https:${fields.image.fields.file.url}`
      : fields.image.fields.file.url
    : null;

