  if (labelless && bordered) {
    // Pair consecutive rows into [headerRow, valueRow] groups, separated by a visual gap.
    const groups: ZimmTableRow[][] = [];
    for (let i = 0; i < rows.length; i += 2) groups.push(rows.slice(i, i + 2));
    // Derive total column count from the maximum span sum across all rows.
    const totalCols = Math.max(...rows.map((row) => (row.spans ?? row.cells.map(() => 1)).reduce((a, b) => a + b, 0)));
    return (
      <chakra.table __css={styles.table}>
        <chakra.colgroup>
          {Array.from({ length: totalCols }).map((_, i) => (
            <chakra.col key={i} width={`${(100 / totalCols).toFixed(4)}%`} />
          ))}
        </chakra.colgroup>
        <chakra.tbody>
