########## sizeGuideContent.tsx full (for ScrollableTable / mobile scroll / min-width) ##########
import React, { useEffect, useState } from 'react';
import { Box, chakra, VStack, Flex } from '@chakra-ui/react';
import { FormattedMessage } from 'react-intl';
import { ZimmProductDescription } from 'app/components/ui-kits/atoms/zimmProductDescription';
import { ZimmTable } from 'app/components/ui-kits/atoms/zimmTable';
import { isBlankRichText } from 'app/utils/richText';
import type { ContentfulRichText, SizeGuideEntry, SizeGuideTable } from 'app/types/contentful';

export type SizeGuideContentProps = {
  sizeFit?: string;
  sizeGuide: SizeGuideEntry | null;
};

type Unit = 'cm' | 'inch';

// Mirrors foundation/gridSystem breakpoints.md (768px = 48em). Media queries cannot consume
// CSS vars, so this is the one deliberate exception to the var(--zimm-*) convention (css.md > Tokens).
const TABLET_MIN_WIDTH = '48em';

const CM_TO_INCH = 0.393701;

export const convertCm = (n: number) => Math.round(n * CM_TO_INCH * 10) / 10;

/** Converts a single table's rows to display-ready values for the active unit. */
export const toDisplayRows = (table: SizeGuideTable, unit: Unit) =>
  table.rows.map((row) => ({
    label: row.label,
    spans: row.spans,
    isHeader: row.isHeader,
    cells: row.values.map((v) => {
      if (!row.convertible || unit !== 'inch') return v;
      const str = String(v);
      const rangeMatch = str.match(/^(\d+(?:\.\d+)?)\s*[–-]\s*(\d+(?:\.\d+)?)$/);
      if (rangeMatch) return `${convertCm(parseFloat(rangeMatch[1]))}–${convertCm(parseFloat(rangeMatch[2]))}`;
      if (typeof v === 'number') return convertCm(v);
      const trimmed = str.trim();
      if (!/^\d+(?:\.\d+)?$/.test(trimmed)) return v;
      return convertCm(Number(trimmed));
    }),
  }));

/** Minimal inline renderer for Contentful Rich Text documents (paragraphs + bold/italic marks). */
const renderMeasurementInstructions = (doc: ContentfulRichText): React.ReactNode =>
  doc.content.map((block, i) => {
    if (block.nodeType !== 'paragraph' || !block.content) return null;
    return (
      <chakra.p key={i} textStyle="caption" color="var(--zimm-color-text-default)" margin={0}>
        {block.content.map((inline, j) => {
          if (inline.nodeType !== 'text') return null;
          let node: React.ReactNode = inline.value ?? '';
          if (inline.marks?.some((m) => m.type === 'bold')) node = <strong key={j}>{node}</strong>;
          if (inline.marks?.some((m) => m.type === 'italic')) node = <em key={j}>{node}</em>;
          return <React.Fragment key={j}>{node}</React.Fragment>;
        })}
      </chakra.p>
    );
  });

type NavItemProps = { label: string; active: boolean; onClick: () => void };
type UnitToggleProps = { unit: Unit; onChange: (u: Unit) => void };
type TableSectionProps = {
  heading?: React.ReactNode;
  description?: string;
  toggle?: React.ReactNode;
  children: React.ReactNode;
};
type ScrollableTableProps = { table: SizeGuideTable; unit: Unit };
type ConvertibleTableSectionProps = {
  table: SizeGuideTable;
  heading?: React.ReactNode;
  description?: string;
  showToggle: boolean;
  initialUnit: Unit;
};

const NavItem = ({ label, active, onClick }: NavItemProps) => (
  <chakra.button
    height="var(--zimm-scale-xl)"
    display="flex"
    flexDirection="column"
    alignItems="flex-start"
    justifyContent="center"
    flexShrink={0}
    sx={{ background: 'none', padding: 0, borderWidth: 0, cursor: 'pointer' }}
    aria-pressed={active}
    onClick={onClick}
  >
    <chakra.span
      display="flex"
      alignItems="center"
      paddingY="var(--zimm-scale-2xs)"
      sx={{
        borderBottomWidth: active ? 'var(--zimm-border-width-default)' : 0,
        borderBottomStyle: 'solid',
        borderBottomColor: active ? 'var(--zimm-color-border-focus)' : 'transparent',
      }}
    >
      <chakra.span
        textStyle="navigation"
        color="var(--zimm-color-text-default)"
        sx={{ whiteSpace: 'nowrap' }}
      >
        {label}
      </chakra.span>
    </chakra.span>
  </chakra.button>
);

const UnitToggle = ({ unit, onChange }: UnitToggleProps) => (
  <Flex gap="var(--zimm-scale-2xs)" role="group" aria-label="Unit" align="center">
    <NavItem label="CM" active={unit === 'cm'} onClick={() => onChange('cm')} />
    <chakra.span
      height="var(--zimm-scale-xl)"
      display="flex"
      flexDirection="column"
      alignItems="flex-start"
      justifyContent="center"
      flexShrink={0}
    >
      <chakra.span display="flex" alignItems="center" paddingY="var(--zimm-scale-2xs)">
        <chakra.span textStyle="navigation" color="var(--zimm-color-text-muted)" aria-hidden="true">
          |
        </chakra.span>
      </chakra.span>
    </chakra.span>
    <NavItem label="INCH" active={unit === 'inch'} onClick={() => onChange('inch')} />
  </Flex>
);

/**
 * One table section: a Flex header row (heading left, optional toggle right), an optional
 * description paragraph, then the table. Spacing matches the Size Guide drawer design (SFCC-102).
 */
const TableSection = ({ heading, description, toggle, children }: TableSectionProps) => (
  <VStack align="stretch" spacing="var(--zimm-scale-2xl)" width="100%">
    {(heading || toggle) && (
      <Flex justify="space-between" align="center" width="100%">
        {heading && (
          <chakra.h2 textStyle="productNames" color="var(--zimm-color-text-default)" margin={0}>
            {heading}
          </chakra.h2>
        )}
        {toggle}
      </Flex>
    )}
    {description && (
      <chakra.p textStyle="caption" color="var(--zimm-color-text-default)" margin={0}>
        {description}
      </chakra.p>
    )}
    {children}
  </VStack>
);

/**
 * Wraps a ZimmTable with a right-edge fade on mobile to hint at horizontal scroll.
 * Outer Box is position:relative with an ::after pseudo-element for the fade gradient;
 * inner Box handles overflow-x:auto so the pseudo-element is not clipped.
 */
const ScrollableTable = ({ table, unit }: ScrollableTableProps) => (
  <Box
    position="relative"
    sx={{
      _after: {
        content: '""',
        position: 'absolute',
        top: 0,
        right: 0,
        bottom: 0,
        width: 'calc(var(--zimm-scale-4xl) + var(--zimm-scale-xs))',
        pointerEvents: 'none',
        zIndex: 1,
        background: `linear-gradient(to right, transparent, var(--zimm-color-grey-white))`,
        display: 'block',
      },
      [`@media (min-width: ${TABLET_MIN_WIDTH})`]: {
        _after: { display: 'none' },
      },
    }}
  >
    <Box overflowX="auto">
      <ZimmTable
        columns={table.labelless ? [] : ['SIZE', ...table.columns]}
        columnSpan={table.columnSpan}
        subColumns={table.subColumns}
        rows={toDisplayRows(table, unit)}
        labelless={table.labelless}
        bordered={table.labelless}
      />
    </Box>
  </Box>
);

/**
 * Self-contained table section that manages its own cm/inch unit state independently.
 * Each instance's toggle only affects its own table, not sibling tables.
 */
