########## zimmTable/index.tsx FULL ##########
import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { BORDER_SECONDARY, BORDER_FOCUS } from './zimmTable.css';

const ZIMM_TABLE_RECIPE = 'ZimmTable';

export type ZimmTableRow = {
  label: string;
  cells: readonly (string | number)[];
  spans?: readonly number[];
  /** When true, renders this row as a bold group sub-header (labelless mode only). */
  isHeader?: boolean;
};

export type ZimmTableProps = {
  columns: readonly string[];
  /** Sub-columns per main column. When > 1, main column headers span this many cells. */
  columnSpan?: number;
  /**
   * Sub-column labels rendered in a second thead row. Each label repeats once per main
   * column group (excluding the label column). The label column spans both header rows
   * via rowSpan=2. Used for the gloves table (S/M | M/L repeating under SHORT/LONG GLOVES).
   */
  subColumns?: readonly string[];
  rows: readonly ZimmTableRow[];
  /**
   * Omits the label column and thead entirely. Rows alternate between isHeader=true
   * (bold group header rendered as th) and isHeader=false (measurement values).
   * Used for the hat table's 3-level grouped layout.
   */
  labelless?: boolean;
  /**
   * Used with labelless: renders vertical cell dividers (borderLeft on non-first cells)
   * instead of row striping. Header rows get a dark bottom border; value rows get a light one.
   * Matches the Figma hat table variant.
   */
  bordered?: boolean;
};

/**
 * Generic data table atom for the Size Guide drawer (SFCC-102).
 * Caller is responsible for passing display-ready values — unit conversion
 * happens upstream in SizeGuideContent, not here.
 *
 * columnSpan enables grouped headers (e.g. belt tables where XS/S spans 2 data columns).
 * row.spans controls per-cell colspan for merged rows. Omitting both fields preserves the
 * standard single-level layout used by clothing/shoe tables.
