const MIN_COL_WIDTH = 'calc(var(--zimm-scale-4xl) + var(--zimm-scale-m))';

/** Reused as Chakra style prop values in index.tsx for conditional border logic. */
export const BORDER_SECONDARY = `var(--zimm-border-width-default) solid var(--zimm-color-border-secondary)`;
export const BORDER_FOCUS = `var(--zimm-border-width-default) solid var(--zimm-color-border-focus)`;

/**
 * Recipe for the ZimmTable data table atom (SFCC-102).
 *
 * Three variants mirror the three render branches in index.tsx:
 *   standard  — labelled table with column headers and a row-label column
 *   labelless — groups of isHeader/value rows, no thead, stripe background
 *   bordered  — labelless + fixed-width columns, vertical cell dividers, group spacers
 *
 * Static base styles (text, colour, horizontal padding) live here; conditional styles
 * (borderBottom, borderRight, textAlign, colSpan, row bg) are applied as direct Chakra
 * props in the component so branching logic stays in JSX.
 */
export const ZimmTable = {
  parts: ['table', 'th', 'td', 'labelTd', 'spacerTd'],
  baseStyle: {
    table: {
      width: '100%',
      borderCollapse: 'collapse',
      // auto is the correct default for standard and labelless; bordered overrides to fixed.
      tableLayout: 'auto',
    },
    // Shared header cell base: text style, colour, horizontal padding, nowrap.
    // Vertical padding and textAlign differ by variant/column — applied as direct props.
    th: {
      textStyle: 'navigation',
      color: 'var(--zimm-color-text-default)',
      paddingX: 'var(--zimm-scale-2xs)',
      whiteSpace: 'nowrap',
    },
    // Shared data cell base: text style, colour, horizontal padding.
    // Vertical padding, textAlign, and minWidth differ by variant/role — applied as direct props.
    td: {
      textStyle: 'caption',
      color: 'var(--zimm-color-text-default)',
      paddingX: 'var(--zimm-scale-2xs)',
    },
    // Label column cell in standard mode: always left-aligned with full vertical padding and
    // a minimum width to prevent the label column from collapsing under narrow viewports.
    labelTd: {
      textStyle: 'caption',
      color: 'var(--zimm-color-text-default)',
      textAlign: 'left',
      paddingX: 'var(--zimm-scale-2xs)',
      paddingY: 'var(--zimm-scale-xl)',
      minWidth: MIN_COL_WIDTH,
    },
    // Spacer row inserted between groups in labelless+bordered mode.
    // border:'none' prevents the collapsed border from bleeding through.
    spacerTd: {
      height: 'var(--zimm-scale-xl)',
      padding: 0,
      border: 'none',
    },
  },
  variants: {
    // Standard labelled table: compact thead padding, generous cell padding, enforced minWidth.
    standard: {
      th: {
        paddingTop: 'var(--zimm-scale-xs)',
        paddingBottom: 'var(--zimm-scale-m)',
        minWidth: MIN_COL_WIDTH,
      },
      td: {
        paddingY: 'var(--zimm-scale-xl)',
        whiteSpace: 'nowrap',
        minWidth: MIN_COL_WIDTH,
      },
    },
    // Labelless: rows alternate isHeader/value, stripe bg applied via tr.bg prop in component.
    labelless: {
      th: { paddingY: 'var(--zimm-scale-xl)' },
      td: { paddingY: 'var(--zimm-scale-xl)', whiteSpace: 'nowrap' },
    },
    // Labelless + bordered: fixed-width equal columns with vertical dividers and group spacers.
    bordered: {
      table: { tableLayout: 'fixed' },
      th: { paddingY: 'var(--zimm-scale-xl)' },
      td: { paddingY: 'var(--zimm-scale-xl)', whiteSpace: 'nowrap' },
    },
  },
  defaultProps: { variant: 'standard' },
};

